  `is_active` tinyint(1) DEFAULT 1,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_business` (`business_id`),
  KEY `idx_active` (`is_active`),
  KEY `idx_expires` (`expires_at`),
  KEY `manage_announcements_creator_fk` (`created_by`),
  CONSTRAINT `manage_announcements_business_fk` FOREIGN KEY (`business_id`) REFERENCES `manage_businesses` (`id`) ON DELETE CASCADE,
  CONSTRAINT `manage_announcements_creator_fk` FOREIGN KEY (`created_by`) REFERENCES `manage_employees` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
