INSERT INTO `support_messages` VALUES
(1,1,1,'Hello from test!','2026-02-21 16:12:07',NULL),
(9,1,669,'Hello! There is no place to set the path for FFmpeg in the settings','2026-03-01 15:07:17',NULL),
(10,1,12,'Yeah, true, I\'ll add that in the next update, thanks for reminding me.','2026-03-02 09:15:46',NULL),
(11,1,671,'Hey i am using the app on android where can i find the downloaded files','2026-03-05 00:15:03',NULL),
(12,1,12,'You can find that in settings, there you\'ll have to select a folder where the downloaded files are downloaded to','2026-03-05 09:36:03',NULL),
(13,1,672,'I keep getting an error when trying to run the file saying: error while loading shared libraries: libmedia_kit_video_plugin.so: cannot open shared object file: No such file or directory','2026-03-08 05:45:21',NULL),
(14,1,12,'If you\'re on Linux, that\'s an error I\'m currently working on solving, thanks for telling me about it.','2026-03-11 08:40:48',NULL),
(15,1,678,'hey you crypto minining virus sucks','2026-03-15 23:47:11','2026-05-02 19:00:59'),
(16,1,12,'it has been removed','2026-03-17 12:46:30',NULL),
(17,1,12,'There is no more cryptominer inside of it.','2026-03-17 12:47:15',NULL),
(18,1,12,'Though it wasn\'t a virus, simply a feature you could chose to enable.','2026-03-17 12:50:21',NULL),
(19,1,12,'If you chose not to enable it, nothing related to cryptomining would have been installed to your pc, so don\'t worry, I never distributed any malware or virus.','2026-03-17 12:50:50',NULL),
(20,1,12,'With the release of v6.0.0, the built-in cryptominer has been completely removed from the application. We want to clarify that this was always a strictly opt-in feature. Designed for users to support development on their hardware only if they explicitly choose to do so.\n\nIf you never enabled this feature, no mining components were ever installed or run on your system. Convert The Spire Reborn remains 100% open-source and is committed to user privacy. We have moved toward a direct support model (GitHub Sponsors) to keep the app clean and lightweight for everyone.','2026-03-17 13:47:30',NULL),
(21,1,12,'I\'ll be reducing ads on the site due to public response that too many ads are present on the site','2026-04-20 07:39:12',NULL),
(22,1,679,'How can i download playlists with more than 100 videos?','2026-04-26 08:51:21','2026-05-02 15:24:46'),
(23,1,679,'Im generally pretty unhappy with the App as it is.','2026-04-26 09:05:46','2026-05-02 15:24:40'),
(24,1,679,'Why isnt there a simple option to add a playlist, choose format AND','2026-04-26 09:06:12','2026-05-02 15:24:39'),
(25,1,679,'quality and download? Feels really strange, clunky and unintuitive right now','2026-04-26 09:07:10','2026-05-02 15:24:38'),
(26,1,679,'I will gladly support my youtube downloader, but, i dont think this will be it...','2026-04-26 09:10:50','2026-05-02 15:24:38'),
(27,1,12,'Literally the first thing you see let\'s you download playlists with 100+ videos, you clearly didn\'t use the app.','2026-04-26 11:42:13',NULL),
(28,1,12,'If you don\'t understand something you can watch the YouTube video featured on the site.','2026-04-26 11:44:13',NULL),
(29,1,12,'All feedback is welcome.','2026-04-26 11:47:32',NULL),
(30,1,12,'Just don\'t lie 🤥 about stuff.','2026-04-26 11:49:10',NULL),
(31,1,679,'Literally the first thing that the app did, is restricting my playlist to 100 downloads.','2026-04-26 16:08:47','2026-05-02 15:24:32'),
(32,1,679,'Fix your program, before you call somebody a lier. Which clearly a really bad idea, if you wish financial support...','2026-04-26 16:09:43','2026-05-02 15:24:31'),
(33,1,679,'Goodbye','2026-04-26 16:09:53','2026-05-02 15:24:30'),
(34,1,12,'what?','2026-04-29 09:58:50','2026-05-02 20:03:02'),
(35,1,12,'It doesn\'t, though, there are literally screenshots on the site now that proof the opposite.','2026-04-29 09:59:16',NULL),
(36,1,12,'When you open the app, the first thing you see is quick downloads, which lets you download 100+ videos.','2026-04-29 10:05:55',NULL),
(37,1,12,'All feedback is welcome, don\'t lie about stuff.','2026-04-29 13:04:35',NULL),
(38,1,683,'Hello. Thank you for making such a wonderful app. Lately I\'ve been having issues downloading playlists and I was wondering if this is a known bug or an issue on my end. Basically I can download individual songs, but whenever I try to download a playlist, it throws this error: \"Loaded 0 of reported 9 playlist entries. This mismatch usually means some videos are private, deleted, region-restricted or temporarly unavaiable through the API \". This happens with every playlist. I\'m on windows using the latest version (v12.2.17+1247). Thanks in advance.','2026-06-26 13:38:54',NULL),
(39,1,12,'I\'ve been working on solving that issue, but it has proven quite difficult to fix.','2026-06-28 14:28:15',NULL),
(40,1,12,'So yeah, thanks for reporting the issue. A fix is currently being worked on.','2026-06-28 14:29:06',NULL),
(41,1,683,'Ok. Thanks a lot for the response!','2026-06-28 17:13:53',NULL),
(42,1,12,'After the most recent ytdlp update (07/04, Fourth of July), the playlist gathering works again.\nYou can now download playlists again.','2026-07-05 09:51:03',NULL),
(43,1,683,'Thanks for the notice!','2026-07-05 22:34:09',NULL),
(44,8,684,'You can\'t download playlists on the mobile android app','2026-07-09 14:05:00',NULL),
(45,8,684,'Does anyone have the same problem?','2026-07-09 14:05:06',NULL),
(46,8,684,'I used the same link for desktop and mobile, but the mobile version says \"This mismatch usually means some videos are private, deleted, region-restricted, or temporarily unavailable through the API\"','2026-07-09 14:06:48',NULL),
(47,8,684,'I\'d send screenshots but there\'s no way to do that','2026-07-09 14:07:28',NULL),
(48,8,684,'I\'m noticing a bit more problems, it seems to be able to show the playlist on the \"playlist\" option, but then it doesn\'t show anything once i put it on the downloading section','2026-07-09 14:21:04',NULL),
(49,8,684,'I never had this problem before the reborn app, I don\'t understand what\'s happening','2026-07-09 14:23:42',NULL),
(50,1,684,'Playlist download still broken, hoping for an update','2026-07-13 10:53:29',NULL),
(51,1,12,'On what device is playlist downloading broken?\nAs on pc it works, though it might not work on mobile, because YouTube Explode takes longer to update.','2026-07-19 09:12:56',NULL),
(52,1,684,'I\'m having the same problem for both pc and mobile. After pasting the link, nothing shows up on the \"Select tracks to download\". I haven\'t changed anything after I downloaded the app itself, so I can\'t fully say this is a me problem. If need be, I\'m willing to stream this or record it and show it to you.','2026-07-23 02:28:54',NULL),
(53,1,12,'Older PC\'s sometimes have issues automatically updating ytdlp.','2026-07-25 19:39:59',NULL),
(54,1,12,'Thanks for the help. I\'ll try improving it to make sure it\'ll work better on your device.','2026-07-25 19:41:16',NULL),
(55,8,12,'Thanks for reporting the bugs. I\'ll look into it, though it\'s possible that on your pc you might need to manually update ytdlp from https://github.com/yt-dlp/yt-dlp at https://github.com/yt-dlp/yt-dlp/releases/tag/2026.07.04, as automatic updates can sometimes fail on older pc\'s.','2026-07-26 11:28:13',NULL),
(56,8,12,'though, thinking about it, I\'m likely going to make it so that entering a playlist link brings you to the playlist option, and make it a little eassier to use','2026-07-26 14:13:16',NULL),
(57,1,12,'though, thinking about it, I\'m likely going to make it so that entering a playlist link brings you to the playlist option, and make it a little eassier to use','2026-07-26 14:13:23',NULL),
(58,1,12,'I made an update that fixed the issue, thanks a lot for reporting this bug.','2026-07-28 10:51:37',NULL),
(59,8,12,'I made an update that fixed the issue, thanks a lot for reporting this bug.','2026-07-28 10:51:44',NULL),
(60,1,684,'Awesome theyre working perfectly fine now, thank you very much for the help!!','2026-08-01 06:48:34',NULL),
(61,1,684,'If there\'s ever a fix to the mobile version, please let me know!!','2026-08-01 06:54:19',NULL),
(62,1,12,'oh, that\'s funny, I just made a fix for it','2026-08-01 08:58:30',NULL),
(63,1,12,'I updated the dependency of youtube-explode, so it should work now on mobile again.','2026-08-01 08:58:59',NULL),
(64,1,684,'THANK YOU VERY MUCH. I just checked and there was a new update, keep up with the awesome work!!!','2026-08-01 10:09:08',NULL),
(65,1,684,'Ah, I just updated it and I seem to be having the same problem still. Perhaps I\'m doing something wrong? I\'ll retry it in like a few days to see if it magically fixed itself lol, sorry for the trouble!','2026-08-01 10:16:19',NULL),
(66,1,12,'No worries. YouTube updates it\'s api pretty frequently, so it\'s difficult to keep the app working. I\'m happy to see you\'re enjoying the app.','2026-08-02 17:49:21',NULL),
(67,1,688,'Hi I\'m new to the app. I\'ve just downloaded the files take them out of the zip folder and run the application. I\'ve got the like app come up, looks great but none of my links give me the downloadable file even like individual songs. have I missed a step setting it up or is it just a bug that will be ironed out soon?','2026-09-11 09:07:56',NULL),
(68,1,12,'Thanks for reporting the issue, I\'ve experienced that the app works differently on different pc\'s, so I\'m currently looking into fixing issues like that, would love if you could describe if you got a certain error, if it says error page needs to reload, then it\'s one of the issues I\'m currently working on.','2026-09-11 10:22:55',NULL),
(69,1,12,'The next update I\'m working on should fix the issue you are having, thanks for reporting it','2026-09-12 17:45:11',NULL),
(70,1,12,'The new update fixed the issue of it no longer downloading songs on certain hardware.','2026-09-13 06:51:54',NULL);
