/*!50003 CREATE*/ /*!50017 DEFINER=`quiz_user`@`localhost`*/ /*!50003 TRIGGER users_before_update
BEFORE UPDATE ON users
FOR EACH ROW
BEGIN
    DECLARE banned_word_found INT DEFAULT 0;
    DECLARE random_string VARCHAR(10);
    DECLARE counter INT DEFAULT 0;
    
    -- Check against banned_words_username table (partial matching)
    SELECT 1 INTO banned_word_found
    FROM banned_words_username 
    WHERE severity = 'block'
    AND (LOCATE(LOWER(word), LOWER(NEW.first_name)) > 0 
         OR LOCATE(LOWER(word), LOWER(NEW.last_name)) > 0)
    LIMIT 1;
    
    -- Check against bannedWords table (partial matching)
    IF banned_word_found = 0 THEN
        SELECT 1 INTO banned_word_found
        FROM bannedWords 
        WHERE LOCATE(LOWER(word), LOWER(NEW.first_name)) > 0 
           OR LOCATE(LOWER(word), LOWER(NEW.last_name)) > 0
        LIMIT 1;
    END IF;
    
    -- If banned word found, generate unique random string
    IF banned_word_found = 1 THEN
        -- Generate random string until we find a unique one
        REPEAT
            SET random_string = CONCAT('User', LPAD(FLOOR(RAND() * 100000), 5, '0'));
            SET counter = counter + 1;
        UNTIL NOT EXISTS (
            SELECT 1 FROM users 
            WHERE (first_name = random_string OR last_name = random_string)
            AND id != NEW.id
        ) OR counter > 10 END REPEAT;
        
        SET NEW.first_name = random_string;
        SET NEW.last_name = 'Player';
    END IF;
END */;;
DELIMITER ;
